<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use Illuminate\Http\Request;
class CategoryController extends Controller { public function index(){return view('admin.categories.index',['categories'=>Category::with('parent')->orderBy('type')->orderBy('name')->paginate(20)]);} public function create(){return view('admin.categories.form',['category'=>new Category]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','type'=>'required|in:product,service','parent_id'=>'nullable|exists:categories,id','icon'=>'nullable|max:100','is_active'=>'nullable|boolean']);$d['is_active']=$r->boolean('is_active');Category::create($d);return redirect()->route('admin.categories.index')->with('success','دسته‌بندی ایجاد شد.');} public function edit(Category $category){return view('admin.categories.form',compact('category'));} public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|max:255','type'=>'required|in:product,service','parent_id'=>'nullable|exists:categories,id','icon'=>'nullable|max:100','is_active'=>'nullable|boolean']);$d['is_active']=$r->boolean('is_active');$category->update($d);return redirect()->route('admin.categories.index')->with('success','دسته‌بندی ویرایش شد.');} public function destroy(Category $category){if($category->ads()->exists())return back()->with('error','این دسته‌بندی آگهی دارد و قابل حذف نیست.');$category->delete();return back()->with('success','حذف شد.');} }
